create extension if not exists pgcrypto;
create table if not exists public.tod_taxonomy (taxonomy_id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, taxonomy_type text not null, active boolean not null default true);
create table if not exists public.tod_organisations (organisation_id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table if not exists public.tod_tenders (tender_id uuid primary key default gen_random_uuid(), buyer_name text not null, reference text, title text not null, created_at timestamptz not null default now());
create table if not exists public.tod_source_documents (document_id uuid primary key default gen_random_uuid(), canonical_slug text not null unique, title text not null, publisher text not null, source_id text not null, document_family text not null, authoritative_url text not null, landing_url text not null, status text not null default 'active' check (status in ('active','superseded','missing','rejected')), first_seen_at timestamptz not null, latest_seen_at timestamptz not null);
create table if not exists public.tod_document_versions (version_id uuid primary key default gen_random_uuid(), document_id uuid not null references public.tod_source_documents(document_id), run_id uuid, download_url text not null, final_resolved_url text, http_status integer not null, content_type text not null, content_length bigint, etag text, last_modified text, sha256 text not null unique, original_filename text, storage_bucket text not null default 'tod-official', storage_path text not null, discovered_at timestamptz not null, downloaded_at timestamptz, immutable boolean not null default true);
create table if not exists public.tod_source_excerpts (excerpt_id uuid primary key default gen_random_uuid(), version_id uuid not null references public.tod_document_versions(version_id), page_start integer not null, page_end integer not null, heading_path text[] not null default '{}', text_content text not null, text_sha256 text not null, extractor_name text not null, extractor_version text not null, confidence numeric not null check (confidence between 0 and 1));
create table if not exists public.tod_inspection_runs (inspection_run_id uuid primary key default gen_random_uuid(), tender_id uuid not null references public.tod_tenders(tender_id), status text not null default 'open', locked_at timestamptz);
create table if not exists public.tod_inspection_sources (inspection_run_id uuid not null references public.tod_inspection_runs(inspection_run_id), version_id uuid not null references public.tod_document_versions(version_id), primary key (inspection_run_id, version_id));
create table if not exists public.tod_compliance_checks (check_id uuid primary key default gen_random_uuid(), inspection_run_id uuid not null references public.tod_inspection_runs(inspection_run_id), outcome text not null, evidence_excerpt_ids uuid[] not null default '{}');
create table if not exists public.tod_ingestion_runs (run_id uuid primary key default gen_random_uuid(), started_at timestamptz not null, finished_at timestamptz, status text not null);
create table if not exists public.tod_ingestion_events (event_id uuid primary key default gen_random_uuid(), run_id uuid references public.tod_ingestion_runs(run_id), event_type text not null, payload jsonb not null default '{}', occurred_at timestamptz not null default now());
create table if not exists public.tod_document_module_routes (document_id uuid not null references public.tod_source_documents(document_id), excerpt_id uuid references public.tod_source_excerpts(excerpt_id), module_code text not null, role text not null check (role in ('primary','secondary')), primary key (document_id, module_code));
create index if not exists tod_versions_document_idx on public.tod_document_versions(document_id);
create index if not exists tod_excerpts_version_idx on public.tod_source_excerpts(version_id);
